#pragma once

#include <stdint.h>

char RuleStateManager(char state, char cState);

/* Next state of 64 cells at once. s0..s3 are the bits of each cell's
 * neighbour count, alive is the current state. Generated by BSGenerator. */
static inline uint64_t RuleBits(uint64_t s0, uint64_t s1, uint64_t s2, uint64_t s3, uint64_t alive) {
  (void)s0; (void)s1; (void)s2; (void)s3; (void)alive;
  return (~s2 & s1 & alive)
       | (~s2 & s1 & s0);
}
